import { PieChart, usePieChart } from '@dreadnought/ui/react';
const data=[{id:'a',label:'A',value:60},{id:'b',label:'B',value:40}];
function Summary(){const {visible}=usePieChart();return <p>Видимых: {visible.length}</p>;}
export function Example(){return <PieChart label="Данные" data={data} innerRadius={0.6}><Summary/><PieChart.Legend>{({defaultContent})=><span>{defaultContent}</span>}</PieChart.Legend><PieChart.Plot tooltipContent={({defaultContent})=><div>{defaultContent}</div>}>{({defaultContent})=>defaultContent}</PieChart.Plot><PieChart.Table/></PieChart>;}
